});

export default function BlogListingPage() {
  try {
    const posts = getBlogPosts({ locale: "en" });
    const jsonLd = buildBlogListingJsonLd(posts);

    return (
      <PageShell className="gap-8">
        <SectionHeader
          eyebrow="Blog"
          title="Guides and updates"
