"use server";

/**
 * Sign-up server action.
 *
 * Creates a new credentials-based account, then immediately signs the user in
 * using the Credentials provider so they land in an authenticated session.
 *
 * Flow:
 *  1. Validate input with Zod.
 *  2. Rate-limit by email (prevents enumeration bursts).
 *  3. Check whether the email is already registered.
 *  4. Hash the password with bcrypt.
 *  5. Resolve or create the CUSTOMER role.
 *  6. Insert the User record.
 *  7. Call signIn("credentials") ΓåÆ Auth.js creates the JWT session + redirects.
 */

import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { AuthError } from "next-auth";
import { RoleKey } from "@/lib/auth/roles";

import { signIn } from "@/auth";
import { routes } from "@/config/routes";
import { signUpValidator } from "@/features/auth/validators";
import { hashPassword } from "@/lib/auth/password";
import { toActionErrorState } from "@/lib/errors/handling";
import { logger } from "@/lib/logger";
import { checkRateLimit } from "@/lib/rate-limit";
import { assertTrustedOrigin, getClientIp } from "@/lib/security/csrf";
import { validateWithSchema } from "@/lib/security/validation";
import { getPrismaClient } from "@/server/db";

export interface SignUpActionState {
  errors?: string[];
  success?: boolean;
}

/**
 * Sign-up server action ΓÇö compatible with React 19 `useActionState`.
 */
export async function signUpAction(
  _prev: SignUpActionState | null,
  formData: FormData,
): Promise<SignUpActionState> {
  const db = getPrismaClient();

  try {
    await assertTrustedOrigin({ action: "auth:sign-up" });
  } catch (error) {
    return toActionErrorState(error, "sign-up");
  }

  // ΓöÇΓöÇ 1. Parse & validate ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const raw = {
    name: formData.get("name") ?? undefined,
    email: formData.get("email"),
    password: formData.get("password"),
    confirmPassword: formData.get("confirmPassword"),
  };

  const parsed = validateWithSchema(signUpValidator, raw);
  if (!parsed.success) {
    return {
      errors: parsed.errors,
    };
  }

  const { name, email, password } = parsed.data;

  // ΓöÇΓöÇ 2. Rate limit (Redis-backed when configured; memory fallback for local) ΓöÇΓöÇ
  const headerList = await headers();
  const ip = getClientIp(headerList);

  // IP-only bucket ΓÇö primary enumeration guard. An attacker cycling through
  // different email addresses cannot create fresh buckets to evade this limit.
  const ipRlResult = await checkRateLimit({
    identifier: ip,
    action: "auth:sign-up",
    limit: 10,
    windowMs: 60_000,
  });

  if (!ipRlResult.success) {
    return {
      errors: ["Too many sign-up attempts. Please wait a minute and try again."],
    };
  }

  // Per-email bucket ΓÇö secondary limit to slow concentrated attempts against a
  // single address (e.g. credential-stuffing a known email).
  const emailRlResult = await checkRateLimit({
    identifier: email.toLowerCase(),
    action: "auth:sign-up:email",
    limit: 3,
    windowMs: 60_000,
  });

  if (!emailRlResult.success) {
    return {
      errors: ["Too many sign-up attempts. Please wait a minute and try again."],
    };
  }

  // ΓöÇΓöÇ 3. Check for duplicate email ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  // Return a generic success-like response for existing emails so an attacker
  // cannot distinguish a registered address from an unregistered one (i.e. no
  // email enumeration via differing error vs. success responses).
  const existing = await db.user.findUnique({ where: { email } });
  if (existing) {
    return { success: true };
  }

  // ΓöÇΓöÇ 4. Hash password ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const passwordHash = await hashPassword(password);

  // ΓöÇΓöÇ 5. Resolve CUSTOMER role ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  // Upsert is idempotent: creates the role when missing and avoids unique-
  // constraint races when multiple sign-up requests run concurrently.
  const customerRole = await db.role.upsert({
    where: { key: RoleKey.CUSTOMER },
    create: {
      key: RoleKey.CUSTOMER,
      name: "Customer",
      permissions: [],
    },
    update: {},
  });

  // ΓöÇΓöÇ 6. Create user ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  try {
    await db.user.create({
      data: {
        email,
        name: name || null,
        password: passwordHash,
        roleId: customerRole.id,
      },
    });
  } catch (err) {
    return toActionErrorState(
      err,
      "sign-up:create-user",
      "Could not create your account. Please try again.",
    );
  }

  // ΓöÇΓöÇ 7. Sign in immediately (throws redirect on success) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  try {
    await signIn("credentials", {
      email,
      password,
      redirectTo: routes.storefront.home,
    });
  } catch (err) {
    // Auth.js throws a NEXT_REDIRECT for the redirect ΓÇö re-throw it.
    if (err instanceof AuthError) {
      logger.error("sign-up: auto sign-in failed", { err });
      // User was created; send them to sign-in page to log in manually.
      redirect(routes.auth.signIn);
    }
    throw err; // Re-throw redirect or unexpected errors
  }

  return { success: true };
}

import Link from "next/link";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { routes } from "@/config/routes";

import { formatBlogPublishedDate } from "../service";
import type { BlogListingItem } from "../types";

type BlogPostCardProps = {
  post: BlogListingItem;
};

export function BlogPostCard({ post }: BlogPostCardProps) {
  return (
    <Card className="overflow-hidden">
      <img
        src={post.coverImage.src}
        alt={post.coverImage.alt}
        width={post.coverImage.width}
        height={post.coverImage.height}
        className="bg-muted h-48 w-full object-cover"
        loading="lazy"
      />

      <CardHeader>
        <p className="text-muted-foreground text-xs font-medium uppercase tracking-wide">
          Published {formatBlogPublishedDate(post.publishedAt)}
        </p>
        <CardTitle className="text-xl">
          <Link href={routes.storefront.blogPost(post.slug)} className="hover:text-primary transition-colors">
            {post.title}
          </Link>
        </CardTitle>
        <CardDescription>{post.excerpt}</CardDescription>
      </CardHeader>

      <CardContent>
        <Link
          href={routes.storefront.blogPost(post.slug)}
          className="text-primary text-sm font-semibold hover:underline"
        >
          Read article
        </Link>
      </CardContent>
    </Card>
  );
}

